"use client";

import React, { useState } from "react";
import { Calendar, Filter, MapPin, ChevronRight, Download } from "lucide-react";

const holidays = [
    { name: "Republic Day", date: "Jan 26, 2026", day: "Monday", type: "National", region: "India" },
    { name: "Holi", date: "Mar 3, 2026", day: "Tuesday", type: "Public", region: "North/West India" },
    { name: "Ugadi / Gudi Padwa", date: "Mar 19, 2026", day: "Thursday", type: "Optional", region: "South/West India" },
    { name: "Good Friday", date: "Apr 3, 2026", day: "Friday", type: "Public", region: "Global" },
    { name: "Eid-ul-Fitr", date: "Mar 20, 2026", day: "Friday", type: "Public", region: "Global" },
    { name: "Independence Day", date: "Aug 15, 2026", day: "Saturday", type: "National", region: "India" },
    { name: "Gandhi Jayanti", date: "Oct 2, 2026", day: "Friday", type: "National", region: "India" },
    { name: "Diwali", date: "Nov 8, 2026", day: "Sunday", type: "Public", region: "Global" },
    { name: "Christmas Day", date: "Dec 25, 2026", day: "Thursday", type: "Public", region: "Global" },
];

export default function SimpleHolidayList() {
    const [filter, setFilter] = useState("All");

    const filteredHolidays = holidays.filter(h => 
        filter === "All" || h.type === filter || h.region === filter
    );

    return (
        <div className="mx-auto max-w-4xl p-6 lg:p-12 space-y-8">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <h1 className="text-3xl font-black tracking-tight text-gray-900 dark:text-white uppercase italic">
                        Holiday <span className="text-gray-400 font-medium">2026</span>
                    </h1>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-1">
                        Scheduled breaks and national observances
                    </p>
                </div>
                <button className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-brand-600 bg-brand-50 dark:bg-brand-500/10 px-4 py-2 rounded-xl transition-all hover:bg-brand-100">
                    <Download size={14} /> Export List
                </button>
            </div>

            {/* Simple Filter Strip */}
            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar border-b border-gray-100 dark:border-gray-800">
                {["All", "National", "Public", "Optional", "India"].map((cat) => (
                    <button
                        key={cat}
                        onClick={() => setFilter(cat)}
                        className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                            filter === cat 
                            ? "bg-gray-900 text-white dark:bg-brand-600" 
                            : "text-gray-400 hover:text-gray-900 dark:hover:text-white"
                        }`}
                    >
                        {cat}
                    </button>
                ))}
            </div>

            {/* Focused List View */}
            <div className="space-y-3">
                {filteredHolidays.map((holiday, index) => (
                    <div 
                        key={index}
                        className="group flex items-center justify-between p-5 bg-white dark:bg-gray-900 rounded-[1.5rem] border border-gray-100 dark:border-gray-800 hover:border-brand-500/40 transition-all hover:shadow-sm"
                    >
                        <div className="flex items-center gap-6">
                            {/* Date Badge */}
                            <div className="flex flex-col items-center justify-center w-14 h-14 bg-gray-50 dark:bg-gray-800 rounded-2xl group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
                                <span className="text-[10px] font-black text-gray-400 uppercase">{holiday.date.split(' ')[0]}</span>
                                <span className="text-lg font-black text-gray-900 dark:text-white leading-none">{holiday.date.split(' ')[1].replace(',', '')}</span>
                            </div>

                            <div>
                                <h3 className="text-sm font-black text-gray-900 dark:text-white uppercase tracking-tight">
                                    {holiday.name}
                                </h3>
                                <div className="flex items-center gap-3 mt-1">
                                    <span className="text-[10px] font-bold text-gray-400 uppercase">{holiday.day}</span>
                                    <span className="w-1 h-1 rounded-full bg-gray-200" />
                                    <div className="flex items-center gap-1 text-[10px] font-black text-brand-500 uppercase">
                                        <MapPin size={10} /> {holiday.region}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-4">
                            <span className={`hidden sm:block px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                                holiday.type === 'National' 
                                ? 'bg-purple-50 text-purple-600 border-purple-100' 
                                : 'bg-emerald-50 text-emerald-600 border-emerald-100'
                            }`}>
                                {holiday.type}
                            </span>
                            <ChevronRight size={18} className="text-gray-300 group-hover:text-brand-500 transition-colors" />
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}